import fs from 'node:fs/promises';import path from 'node:path';import http from 'node:http';import {once} from 'node:events';import {createRequire} from 'node:module';import assert from 'node:assert/strict';import worker from '../../worker/index.js';import {MemoryR2} from './memory-r2.mjs';
const require=createRequire(process.env.STUDIO_BROWSER_PACKAGE||new URL('../../package.json',import.meta.url));const {chromium}=require('playwright');
const cookie='ps_owner='+'6'.repeat(32),env={RECORDINGS:new MemoryR2()};let origin,refuseSave=false;
const api=async(url,options={})=>{const response=await worker.fetch(new Request(origin+url,{...options,headers:{origin,cookie,...options.headers}}),env);if(!response.ok)throw Error(await response.text());return response.json()};
const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,origin);let response;if(refuseSave&&req.method==='PUT'&&url.pathname.startsWith('/api/recordings/'))response=Response.json({error:'Synthetic workspace unavailable'},{status:503});else if(url.pathname.startsWith('/api/local/sharing/status'))response=Response.json({available:true,connected:false,links:{}});else if(url.pathname.startsWith('/api/local/status'))response=Response.json({available:false,ai:false,localSpeech:false});else if(url.pathname.startsWith('/api/chatgpt/status'))response=Response.json({available:false,accounts:[],account:null});else if(url.pathname.startsWith('/api/desktop/status'))response=Response.json({available:false});else if(/\.(?:js|css|html|svg)$/.test(url.pathname)&&!url.pathname.slice(1).includes('/')){const name=url.pathname.slice(1),source=['shared.js','decision-policy.js','local-analysis.js'].includes(name)?name:'public/'+name;const bytes=await fs.readFile(source);response=new Response(bytes,{headers:{'content-type':name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':name.endsWith('.svg')?'image/svg+xml':'text/html'}})}else response=await worker.fetch(new Request(origin+req.url,{method:req.method,headers:{...req.headers,cookie},...(!['GET','HEAD'].includes(req.method)?{body:req,duplex:'half'}:{})}),env);res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()))}catch(error){res.writeHead(500);res.end(error.message)}});server.listen(0,'127.0.0.1');await once(server,'listening');origin='http://127.0.0.1:'+server.address().port;
let browser;const results=[],errors=[];try{
 const first=await api('/api/recordings',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});const transcript='Keep the newer saved source. Open the spreadsheet and sort the rows by name.';await api('/api/recordings/'+first.id,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({transcript,transcriptSource:'Manual',segments:[]})});const record=await api('/api/recordings/'+first.id);
 browser=await chromium.launch({channel:'msedge',headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000}});await context.addInitScript(({id,revision})=>{const draft={identity:{id,key:'synthetic-conflict',revision:revision-1},modifiedAt:Date.now()+1000,mode:'paste',transcript:'Recover the older browser draft separately. Copy the invoice total into the report.',segments:[],reviewed:false,result:null};localStorage.setItem('process-studio-record-'+id,JSON.stringify(draft))},{id:first.id,revision:record.revision});const page=await context.newPage();page.on('pageerror',error=>errors.push(error.message));await page.goto(origin+'/recording.html?record='+first.id);await page.waitForSelector('body[data-studio-ready=true]');assert.equal(await page.locator('#transcript').inputValue(),transcript);assert.equal(await page.evaluate(id=>JSON.parse(localStorage.getItem('process-studio-record-'+id)).transcript,first.id),'Recover the older browser draft separately. Copy the invoice total into the report.');results.push('Conflicting browser draft retained; newer saved source opened.');await page.getByRole('button',{name:'Recover browser draft as a separate walkthrough'}).click();await page.waitForFunction(()=>document.getElementById('processProgress').dataset.kind==='done');assert.equal((await api('/api/recordings/'+first.id)).transcript,transcript);assert.equal((await api('/api/recordings')).items.length,2);results.push('Recovery creates a separate walkthrough without replacing the original.');
 await page.locator('#transcript').fill('This current source saves even when browser recovery storage is exhausted. Sort the report by date.');await page.evaluate(()=>{Storage.prototype.setItem=function(){throw new DOMException('Synthetic quota','QuotaExceededError')}});await page.locator('#transcript').dispatchEvent('input');await page.waitForFunction(()=>document.getElementById('processProgress').dataset.kind==='done');const saved=(await api('/api/recordings')).items;assert.equal(saved.length,2);const second=saved.find(item=>item.id!==first.id);assert.match((await api('/api/recordings/'+second.id)).transcript,/current source saves/);results.push('Browser quota failure does not block workspace autosave.');refuseSave=true;await page.locator('#transcript').fill('Keep this newest unsaved source when both stores are unavailable. Sort the rows by name.');await page.waitForFunction(()=>document.getElementById('processProgress').textContent.includes('Workspace save failed and browser recovery storage is unavailable'));const downloadEvent=page.waitForEvent('download');await page.locator('#exportCurrentDraft').click();const download=await downloadEvent;const exported=JSON.parse(await fs.readFile(await download.path(),'utf8'));assert.match(exported.records[0].transcript,/newest unsaved source/);results.push('Combined save failures are explicit; current unsaved text and process remain exportable.');refuseSave=false;
 await context.close();const clean=await browser.newContext();const cachePage=await clean.newPage();cachePage.on('pageerror',error=>errors.push(error.message));await cachePage.goto(origin+'/recording.html');await cachePage.waitForSelector('body[data-studio-ready=true]');const cleanup=await cachePage.evaluate(async()=>{const id='a'.repeat(32),other='b'.repeat(32),draft={identity:{id:null,key:'delete-a'},transcript:'Synthetic private source'};localStorage.setItem('process-studio-latest',JSON.stringify(draft));localStorage.setItem('process-studio-record-'+id,JSON.stringify(draft));localStorage.setItem('process-studio-record-'+other,JSON.stringify({identity:{id:other,key:'keep-b'}}));sessionStorage.setItem('studio-active-job',JSON.stringify({recordId:id,key:'delete-a'}));const db=await new Promise((resolve,reject)=>{const req=indexedDB.open('process-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('recordings');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});await new Promise((resolve,reject)=>{const tx=db.transaction('recordings','readwrite'),store=tx.objectStore('recordings');for(const key of ['latest','delete-a','keep-b'])store.put(new Blob(['synthetic video']),key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();const {discardRecordingCopies}=await import('/browser-cache.js');await discardRecordingCopies(id,{cacheKeys:['delete-a']});const verify=await new Promise(resolve=>{const req=indexedDB.open('process-studio',1);req.onsuccess=()=>resolve(req.result)});const keys=await new Promise(resolve=>{const req=verify.transaction('recordings').objectStore('recordings').getAllKeys();req.onsuccess=()=>resolve(req.result)});verify.close();return {keys,deleted:localStorage.getItem('process-studio-record-'+id),other:!!localStorage.getItem('process-studio-record-'+other),job:sessionStorage.getItem('studio-active-job')}});assert.deepEqual(cleanup,{keys:['keep-b'],deleted:null,other:true,job:null});results.push('Native IndexedDB media and browser/job metadata removed; another recording preserved.');await cachePage.goto(origin+'/recording.html?record='+second.id);await cachePage.waitForSelector('body[data-studio-ready=true]');const otherPage=await clean.newPage();otherPage.on('pageerror',error=>errors.push(error.message));await otherPage.goto(origin+'/recording.html?record='+second.id);await otherPage.waitForSelector('body[data-studio-ready=true]');await cachePage.evaluate(async id=>{await fetch('/api/recordings/'+id,{method:'DELETE'});await fetch('/api/recordings/'+id+'/purge',{method:'DELETE'});window.dispatchEvent(new CustomEvent('recording-deleted',{detail:{id}}))},second.id);await otherPage.waitForFunction(()=>document.getElementById('transcript').value==='');results.push('Permanent deletion clears an open recording in another tab.');assert.deepEqual(errors,[]);await fs.mkdir('research',{recursive:true});await cachePage.screenshot({path:'research/required-fixes-browser.png',fullPage:true});await fs.writeFile('research/required-fixes-browser.json',JSON.stringify({at:new Date().toISOString(),browser:'isolated Edge headless',synthetic:true,results,pageErrors:errors},null,2));console.log(JSON.stringify({results,pageErrors:errors}));
}finally{await browser?.close();server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}

